update public.catalog_items set aliases = (select array_agg(distinct x) from unnest(coalesce(aliases,'{}'::text[]) || array['chorizo artesanal','chorizo hondureno','chorizo hondureño','jamon de cerdo','jamón de cerdo','tocino de cerdo','carne de cerdo cocida','carne de cerdo casera']) x) where subcategory='pork';
